<?php use App\Core\Authorization; ?>
<div class="page-heading"><div><p class="eyebrow">People</p><h1>Teachers</h1><p>Manage faculty profiles and departments.</p></div><?php if(Authorization::allows('teachers.create')):?><div class="list-heading-actions"><a class="button" href="<?=e(url('/teachers/import'))?>">Import CSV</a><a class="button primary" href="<?=e(url('/teachers/create'))?>">Add teacher</a></div><?php endif;?></div>
<form class="filter-bar" method="get" aria-label="Filter teachers"><label class="filter-field">Search<input name="q" value="<?=e($q)?>" placeholder="Employee number or name"></label><label class="filter-field">Status<select name="status"><option value="">All statuses</option><?php foreach(['active','on_leave','inactive','separated'] as $s):?><option <?=$status===$s?'selected':''?> value="<?=$s?>"><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select></label><button class="button">Search teachers</button></form>
<section class="card table-card"><table><thead><tr><th scope="col">Teacher</th><th scope="col">Employee no.</th><th scope="col">Department</th><th scope="col">Status</th><th scope="col" class="action-column">Actions</th></tr></thead><tbody><?php foreach($teachers as $t):?><tr><td><strong><?=e($t['last_name'].', '.$t['first_name'])?></strong><br><small><?=e($t['email'])?></small></td><td><?=e($t['employee_no'])?></td><td><?=e($t['department']??'—')?></td><td><span class="badge"><?=e($t['employment_status'])?></span></td><td><div class="record-actions"><a class="button small" href="<?=e(url('/teachers/'.$t['id']))?>">View</a><?php if(Authorization::isSuperAdministrator()):?><form method="post" action="<?=e(url('/teachers/'.$t['id'].'/delete'))?>" onsubmit="return confirm(<?=e(json_encode('Delete '.$t['first_name'].' '.$t['last_name'].' and all linked records? This cannot be undone.'))?>);"><?php echo \App\Core\Csrf::field(); ?><button class="button small danger-button" type="submit">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$teachers):?><tr><td colspan="5" class="empty">No teachers found.</td></tr><?php endif;?></tbody></table></section>
